import { takePress } from "./takePress.ts";
import type { Offer } from "./offer.ts";

const offer: Offer = {
  seq: 42,
  primary: { id: "roll" as const, label: "Roll", kind: "rollTable" },
  moves: [{ id: "died", label: "I died" }],
  undo: null,
  needsPage: null,
  presets: [],
  setups: [],
  trackers: [],
  clock: null,
  autoRoll: false,
  ending: null,
};
const acts = () => ({
  primary: vi.fn(),
  move: vi.fn(),
  undo: vi.fn(),
